def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 4]
    if not cells:
        return out
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)
    height = bottom - top + 1
    # Replace the 6 marker with a vertically reflected copy of the 4 shape,
    # immediately below the original.
    for r, row in enumerate(out):
        for c, value in enumerate(row):
            if value == 6:
                out[r][c] = 0
    for offset in range(height):
        src_r = bottom - offset
        dst_r = bottom + 1 + offset
        if dst_r >= len(out):
            break
        for c in range(left, right + 1):
            if grid[src_r][c] == 4:
                out[dst_r][c] = 4
    return out
